let sikepoIdentity;
document.querySelectorAll('.brand,.landing-link').forEach(link=>{link.href=location.hostname==='dashboard.sikepo.tech'?'https://sikepo.tech/':'/';});
const roleNames={SA:'Super admin',VK:'Verifikator KC',ST:'Satgas anti fraud',AU:'Auditor'};
async function loadIdentity(){try{const response=await fetch('/api/auth/me',{cache:'no-store'});if(response.status===401){location.replace(location.hostname==='localhost'||location.hostname==='127.0.0.1'?'/login':'https://sikepo.tech/login');return;}if(!response.ok)throw new Error();sikepoIdentity=await response.json();const user=sikepoIdentity.user;document.querySelector('.profile strong').textContent=user.name;document.querySelector('.profile small').textContent=roleNames[user.role]+' · sandbox';document.querySelectorAll('.avatar').forEach(el=>el.textContent=user.role);const logout=document.createElement('button');logout.className='text-button';logout.textContent='Keluar dari workspace';logout.addEventListener('click',async()=>{logout.disabled=true;try{const result=await fetch('/api/auth/logout',{method:'POST',headers:{'X-CSRF-Token':sikepoIdentity.csrf}});if(result.ok){const body=await result.json();location.assign(body.redirect);}else{logout.disabled=false;logout.textContent='Coba keluar lagi';}}catch{logout.disabled=false;}});document.querySelector('.sidebar-bottom').append(logout);}catch{const notice=document.createElement('p');notice.textContent='Sesi belum dapat diverifikasi. Muat ulang halaman.';notice.setAttribute('role','alert');document.querySelector('main').prepend(notice);}}
loadIdentity();
const detailBody=document.querySelector('#detail-body');
new MutationObserver(()=>{if(!detailBody.querySelector('#detail-title')||detailBody.querySelector('[data-ai-explain]'))return;const button=document.createElement('button');button.dataset.aiExplain='';button.className='button black';button.textContent='Jelaskan dengan Gemma';button.addEventListener('click',async()=>{if(!sikepoIdentity)return;button.disabled=true;button.textContent='Gemma menelaah simulasi…';const id=detailBody.querySelector('#detail-title').textContent;const claim=typeof claims!=='undefined'?claims.find(c=>c.id===id):null;const output=document.createElement('div');output.className='detail-notice';button.after(output);try{if(!claim)throw new Error('Data simulasi tidak ditemukan.');const {amount,tariff,los,normalLos,score}=claim;const response=await fetch('/api/investigate',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':sikepoIdentity.csrf},body:JSON.stringify({id,amount,tariff,los,normalLos,score})});const result=await response.json();if(!response.ok)throw new Error(result.error);output.replaceChildren();const summary=document.createElement('p');summary.textContent=result.summary;output.append(summary);const list=document.createElement('ul');result.checks.forEach(text=>{const li=document.createElement('li');li.textContent=text;list.append(li);});output.append(list);const source=document.createElement('small');source.textContent='Gemma · Mastra workflow · Data sintetis. Verifikasi manusia tetap diperlukan.';output.append(source);button.textContent='Penjelasan Gemma';}catch(err){output.textContent=err.message;button.disabled=false;button.textContent='Coba Gemma lagi';}});detailBody.append(button);}).observe(detailBody,{childList:true});
